-- Run only against a disposable local database after the 13E.A migration.
-- All fixtures and assertions are rolled back by the outer transaction.
BEGIN;

DO $validation$
#variable_conflict error
DECLARE
  manager_id uuid;
  recipient_id uuid;
  unrelated_id uuid;
  v_athlete_id uuid := gen_random_uuid();
  v_second_athlete_id uuid := gen_random_uuid();
  a2_id uuid := gen_random_uuid(); a3_id uuid := gen_random_uuid(); a4_id uuid := gen_random_uuid(); a5_id uuid := gen_random_uuid(); a6_id uuid := gen_random_uuid(); staff_team_id uuid;
  b_id uuid := gen_random_uuid(); b_other_id uuid := gen_random_uuid(); b_inv uuid; b_created timestamptz; b_updated timestamptz; b_expiry timestamptz; b_email text; b_inviter uuid; b_hash text;
  c1_id uuid := gen_random_uuid(); c3a_id uuid := gen_random_uuid(); c3b_id uuid := gen_random_uuid(); d1_id uuid := gen_random_uuid(); d2_id uuid := gen_random_uuid(); d1_self uuid; d2_self uuid;
  e1_id uuid := gen_random_uuid(); e2_id uuid := gen_random_uuid(); e_recipient uuid; e1_inv uuid; e2_inv uuid; e1_self uuid; e2_self uuid; e_email text;
  f_id uuid := gen_random_uuid(); f_team uuid; f_inv uuid; f_before_athletes bigint; f_result uuid; f_display text;
  g1a uuid := gen_random_uuid(); g1b uuid := gen_random_uuid(); g1r uuid; g1_email text; g1_inv uuid; g1_count bigint;
  g4a uuid := gen_random_uuid(); g5a uuid := gen_random_uuid(); g6a uuid := gen_random_uuid();
  g_fail_recipient uuid; g_fail_email text; g4_inv uuid; g5_inv uuid; g6_inv uuid; g_before_count bigint;
  g7a uuid := gen_random_uuid(); g8a uuid := gen_random_uuid(); g7_inv uuid; g8_inv uuid;
  g7_created timestamptz; g7_expires timestamptz; g7_email text; g7_hash text;
  g8_created timestamptz; g8_expires timestamptz; g8_status public.team_invitation_status;
  h1a uuid := gen_random_uuid(); h2a uuid := gen_random_uuid(); h3a uuid := gen_random_uuid(); h4a uuid := gen_random_uuid();
  h1r uuid; h2r uuid; h3r uuid; h4r uuid;
  h1_email text; h2_email text; h3_email text; h4_email text; h4_changed_email text;
  h1_inv uuid; h2_inv uuid; h3_inv uuid; h4_inv uuid;
  h_accepted_at timestamptz;
  h5a uuid := gen_random_uuid(); h6a uuid := gen_random_uuid(); h6b uuid := gen_random_uuid(); h7a uuid := gen_random_uuid(); h8a uuid := gen_random_uuid();
  h5r uuid; h6r uuid; h7r uuid; h7w uuid; h8r uuid;
  h5_email text; h6_email text; h7_email text; h8_email text;
  h5_inv uuid; h6_inv1 uuid; h6_inv2 uuid; h7_inv uuid; h8_inv uuid;
  h8_created timestamptz; h8_expires timestamptz;
  i1a uuid := gen_random_uuid(); i2a uuid := gen_random_uuid(); i_good uuid; i_wrong uuid; i_unconfirmed uuid;
  i_email text; i_wrong_email text; i_unconfirmed_email text; i_inv uuid; i2_inv uuid;
  i_expected_display text := 'I private child display'; i_count bigint; i_name text; i_exp timestamptz; i_status text;
  i_inv_before jsonb; i_athlete_before jsonb; i_rel_before bigint;
  j1a uuid := gen_random_uuid(); j2a uuid := gen_random_uuid(); j3a uuid := gen_random_uuid(); j4a uuid := gen_random_uuid(); j4b uuid := gen_random_uuid(); j4c uuid := gen_random_uuid(); j4d uuid := gen_random_uuid(); j6a uuid := gen_random_uuid(); j7a uuid := gen_random_uuid(); j8a uuid := gen_random_uuid(); j8b uuid := gen_random_uuid();
  j_view uuid; j_revoked uuid; j_self uuid; j_staff uuid; j_wrong uuid; j6r uuid;
  j1_inv uuid; j2_inv uuid; j3_inv uuid; j4_inv uuid; j6_inv uuid; j7_inv uuid; j8_inv_a uuid; j8_inv_b uuid;
  j6_email text; j6_accepted timestamptz; j_before_count bigint;
  ka uuid := gen_random_uuid(); kb uuid := gen_random_uuid(); kv uuid; kr uuid; ks uuid; kself uuid; kstaff uuid; kother uuid;
  ka_rev uuid; ka_pending uuid; kb_pending uuid; k_count bigint; k_rel_before bigint; k_ath_before jsonb;
  acl_role text; acl_col text;
  sh_a uuid := gen_random_uuid(); sh_b uuid := gen_random_uuid(); sh_active uuid; sh_revoked uuid; sh_reclaim uuid;
  v_invitation_id uuid;
  v_token text := repeat('a', 64);
  v_second_token text := repeat('b', 64);
  v_hash text := encode(extensions.digest(repeat('a', 64), 'sha256'), 'hex');
  v_second_hash text := encode(extensions.digest(repeat('b', 64), 'sha256'), 'hex');
  v_email text;
  v_result uuid;
  failed boolean;
  v_marker text := '13ea-validator-' || replace(gen_random_uuid()::text, '-', '');
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname='child_login_invitations' AND c.relrowsecurity) THEN RAISE EXCEPTION 'child login invitation table/RLS is missing'; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname IN ('child_login_invitations_email_normalized','child_login_invitations_token_hash_sha256','child_login_invitations_exact_expiry','child_login_invitations_lifecycle') GROUP BY conrelid HAVING count(*)=4) THEN RAISE EXCEPTION 'child login invitation constraints are incomplete'; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname='public' AND tablename='child_login_invitations' AND indexname='child_login_invitations_one_pending_per_athlete') THEN RAISE EXCEPTION 'child login invitation pending uniqueness index is missing'; END IF;
  IF has_table_privilege('authenticated','public.child_login_invitations','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') THEN RAISE EXCEPTION 'authenticated has direct child login invitation table access'; END IF;
  IF to_regprocedure('public.create_child_login_invitation(uuid,text,text)') IS NULL OR to_regprocedure('public.get_child_login_invitation_summary(text)') IS NULL OR to_regprocedure('public.accept_child_login_invitation(text)') IS NULL OR to_regprocedure('public.revoke_child_login_invitation(uuid)') IS NULL OR to_regprocedure('public.list_my_child_login_invitations(uuid)') IS NULL THEN RAISE EXCEPTION 'child login invitation function signatures are incomplete'; END IF;
  IF (SELECT p.prorettype::regtype::text FROM pg_proc p WHERE p.oid='public.create_child_login_invitation(uuid,text,text)'::regprocedure) <> 'record' OR (SELECT p.prorettype::regtype::text FROM pg_proc p WHERE p.oid='public.get_child_login_invitation_summary(text)'::regprocedure) <> 'record' OR (SELECT p.prorettype::regtype::text FROM pg_proc p WHERE p.oid='public.accept_child_login_invitation(text)'::regprocedure) <> 'uuid' OR (SELECT p.prorettype::regtype::text FROM pg_proc p WHERE p.oid='public.revoke_child_login_invitation(uuid)'::regprocedure) <> 'void' OR (SELECT p.prorettype::regtype::text FROM pg_proc p WHERE p.oid='public.list_my_child_login_invitations(uuid)'::regprocedure) <> 'record' THEN RAISE EXCEPTION 'child login invitation return contracts are incomplete'; END IF;
  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('create_child_login_invitation','get_child_login_invitation_summary','accept_child_login_invitation','revoke_child_login_invitation','list_my_child_login_invitations') AND p.prosecdef AND coalesce(p.proconfig, ARRAY[]::text[]) @> ARRAY['search_path=""']::text[] AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('public',p.oid,'EXECUTE')) <> 5 THEN RAISE EXCEPTION 'child login invitation function hardening or phase grants are incorrect'; END IF;

  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
  SELECT gen_random_uuid(),'authenticated','authenticated',v_marker || '-' || n || '@example.test',clock_timestamp(),'{"provider":"email","providers":["email"]}'::jsonb,'{}'::jsonb,clock_timestamp(),clock_timestamp()
  FROM generate_series(1,3) AS n;
  SELECT p.id, lower(btrim(u.email)) INTO manager_id, v_email FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE u.email=v_marker || '-1@example.test';
  SELECT p.id INTO recipient_id FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE u.email=v_marker || '-2@example.test';
  SELECT p.id INTO unrelated_id FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE u.email=v_marker || '-3@example.test';
  IF manager_id IS NULL OR recipient_id IS NULL OR unrelated_id IS NULL THEN RAISE EXCEPTION 'Validator fixture error: requires three confirmed auth-backed profiles'; END IF;
  SELECT lower(btrim(email)) INTO v_email FROM auth.users WHERE id=recipient_id;

  INSERT INTO public.athletes(id,display_name,created_by_profile_id) VALUES (v_athlete_id,'Child login validation athlete',manager_id),(v_second_athlete_id,'Child login validation second athlete',manager_id);
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES (v_athlete_id,manager_id,'guardian',true,true,manager_id),(v_second_athlete_id,manager_id,'guardian',true,true,manager_id);

  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true);
  SELECT c.invitation_id INTO v_invitation_id FROM public.create_child_login_invitation(v_athlete_id,v_email,v_hash) c;
  IF v_invitation_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.child_login_invitations i WHERE i.id=v_invitation_id AND i.expires_at=i.created_at+interval '7 days') THEN RAISE EXCEPTION 'guardian MANAGE creation or exact expiry failed'; END IF;
  failed:=false; BEGIN PERFORM public.create_child_login_invitation(v_athlete_id,v_email,v_second_hash); EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed THEN RAISE EXCEPTION 'one pending child login invitation per athlete was not enforced'; END IF;
  PERFORM set_config('request.jwt.claim.sub',unrelated_id::text,true); failed:=false; BEGIN PERFORM public.create_child_login_invitation(v_second_athlete_id,v_email,v_second_hash); EXCEPTION WHEN insufficient_privilege THEN failed:=true; END; IF NOT failed THEN RAISE EXCEPTION 'non-guardian created child login invitation'; END IF;
  IF EXISTS (SELECT 1 FROM public.get_child_login_invitation_summary(v_token)) THEN RAISE EXCEPTION 'wrong recipient learned child identity'; END IF;
  PERFORM set_config('request.jwt.claim.sub',recipient_id::text,true);
  IF NOT EXISTS (SELECT 1 FROM public.get_child_login_invitation_summary(v_token)) THEN RAISE EXCEPTION 'matching recipient did not receive minimal summary'; END IF;
  SELECT a.athlete_id INTO v_result FROM public.accept_child_login_invitation(v_token) a;
  IF v_result IS DISTINCT FROM v_athlete_id OR NOT EXISTS (SELECT 1 FROM public.athlete_profile_relationships r WHERE r.athlete_id=v_athlete_id AND r.profile_id=recipient_id AND r.role='self' AND r.training_permission AND r.manage_permission AND r.revoked_at IS NULL) THEN RAISE EXCEPTION 'first child self claim was not created'; END IF;
  SELECT a.athlete_id INTO v_result FROM public.accept_child_login_invitation(v_token) a;
  IF v_result IS DISTINCT FROM v_athlete_id THEN RAISE EXCEPTION 'accepted child login invitation was not idempotent'; END IF;
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); SELECT c.invitation_id INTO v_invitation_id FROM public.create_child_login_invitation(v_second_athlete_id,v_email,v_second_hash) c;
  PERFORM set_config('request.jwt.claim.sub',recipient_id::text,true); failed:=false; BEGIN PERFORM public.accept_child_login_invitation(v_second_token); EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed THEN RAISE EXCEPTION 'profile claimed a second active athlete'; END IF;
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); failed:=false; BEGIN PERFORM public.create_child_login_invitation(v_athlete_id,v_email,encode(extensions.digest(repeat('c',64),'sha256'),'hex')); EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed THEN RAISE EXCEPTION 'historical self athlete was reclaimed'; END IF;
  EXECUTE 'SET LOCAL ROLE authenticated'; failed:=false; BEGIN INSERT INTO public.child_login_invitations(athlete_id,invited_email,inviter_profile_id,token_hash) VALUES(v_second_athlete_id,v_email,manager_id,repeat('0',64)); EXCEPTION WHEN insufficient_privilege THEN failed:=true; END; EXECUTE 'RESET ROLE'; IF NOT failed THEN RAISE EXCEPTION 'direct child login invitation write was not denied'; END IF;

  -- Section A: each authority fixture is isolated and calls the real creator.
  INSERT INTO public.athletes(id,display_name,created_by_profile_id) VALUES (a2_id,'A2',manager_id),(a3_id,'A3',manager_id),(a4_id,'A4',manager_id),(a5_id,'A5',manager_id),(a6_id,'A6',manager_id);
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES
    (a2_id,unrelated_id,'guardian',false,false,manager_id),(a3_id,recipient_id,'guardian',true,true,manager_id),(a4_id,manager_id,'self',true,true,manager_id),(a6_id,manager_id,'guardian',true,true,manager_id);
  UPDATE public.athlete_profile_relationships SET revoked_at=clock_timestamp() WHERE athlete_id=a3_id AND profile_id=recipient_id;
  INSERT INTO public.teams(name,created_by_user_id) VALUES('13EA validator staff',manager_id) RETURNING id INTO staff_team_id;
  INSERT INTO public.team_staff_memberships(team_id,profile_id,role,created_by_profile_id) VALUES(staff_team_id,unrelated_id,'coach',manager_id);
  PERFORM set_config('request.jwt.claim.sub',unrelated_id::text,true); failed:=false; BEGIN PERFORM public.create_child_login_invitation(a2_id,v_email,encode(extensions.digest(repeat('2',64),'sha256'),'hex')); EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed OR EXISTS(SELECT 1 FROM public.child_login_invitations WHERE athlete_id=a2_id) THEN RAISE EXCEPTION 'A2 guardian manage=false authorization failure'; END IF;
  PERFORM set_config('request.jwt.claim.sub',recipient_id::text,true); failed:=false; BEGIN PERFORM public.create_child_login_invitation(a3_id,v_email,encode(extensions.digest(repeat('3',64),'sha256'),'hex')); EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed OR EXISTS(SELECT 1 FROM public.child_login_invitations WHERE athlete_id=a3_id) THEN RAISE EXCEPTION 'A3 revoked guardian authorization failure'; END IF;
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); failed:=false; BEGIN PERFORM public.create_child_login_invitation(a4_id,v_email,encode(extensions.digest(repeat('4',64),'sha256'),'hex')); EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed OR EXISTS(SELECT 1 FROM public.child_login_invitations WHERE athlete_id=a4_id) THEN RAISE EXCEPTION 'A4 self manage authorization failure'; END IF;
  PERFORM set_config('request.jwt.claim.sub',unrelated_id::text,true); failed:=false; BEGIN PERFORM public.create_child_login_invitation(a5_id,v_email,encode(extensions.digest(repeat('5',64),'sha256'),'hex')); EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed OR EXISTS(SELECT 1 FROM public.child_login_invitations WHERE athlete_id=a5_id) THEN RAISE EXCEPTION 'A5 team_staff_memberships coach authorization failure'; END IF;
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); SELECT c.invitation_id INTO v_invitation_id FROM public.create_child_login_invitation(a6_id,(SELECT lower(btrim(email)) FROM auth.users WHERE id=manager_id),encode(extensions.digest(repeat('6',64),'sha256'),'hex')) c; IF v_invitation_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=v_invitation_id AND athlete_id=a6_id AND inviter_profile_id=manager_id AND status='pending') THEN RAISE EXCEPTION 'A6 own email invitation failure'; END IF;
  RAISE NOTICE 'A1 PASS'; RAISE NOTICE 'A2 PASS'; RAISE NOTICE 'A3 PASS'; RAISE NOTICE 'A4 PASS'; RAISE NOTICE 'A5 PASS'; RAISE NOTICE 'A6 PASS';

  -- Section B: valid direct mutations exercise the immutable update trigger.
  INSERT INTO public.athletes(id,display_name,created_by_profile_id) VALUES(b_id,'B',manager_id),(b_other_id,'B other',manager_id);
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(b_id,manager_id,'guardian',true,true,manager_id),(b_other_id,manager_id,'guardian',true,true,manager_id);
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); SELECT c.invitation_id INTO b_inv FROM public.create_child_login_invitation(b_id,v_email,encode(extensions.digest(repeat('q',64),'sha256'),'hex')) c;
  SELECT created_at,updated_at,expires_at,invited_email,inviter_profile_id,token_hash INTO b_created,b_updated,b_expiry,b_email,b_inviter,b_hash FROM public.child_login_invitations WHERE id=b_inv;
  IF b_created IS NULL OR b_updated IS NULL OR b_expiry IS NULL OR b_created<>b_updated THEN RAISE EXCEPTION 'B1 timestamps failed'; END IF; RAISE NOTICE 'B1 PASS';
  IF b_expiry<>b_created+interval '7 days' THEN RAISE EXCEPTION 'B2 expiry failed'; END IF; RAISE NOTICE 'B2 PASS';
  failed:=false; BEGIN UPDATE public.child_login_invitations SET created_at=b_created+interval '1 second' WHERE id=b_inv; EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed OR (SELECT created_at FROM public.child_login_invitations WHERE id=b_inv)<>b_created THEN RAISE EXCEPTION 'B3 immutable failed'; END IF; RAISE NOTICE 'B3 PASS';
  failed:=false; BEGIN UPDATE public.child_login_invitations SET expires_at=b_expiry+interval '1 second' WHERE id=b_inv; EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed OR (SELECT expires_at FROM public.child_login_invitations WHERE id=b_inv)<>b_expiry THEN RAISE EXCEPTION 'B4 immutable failed'; END IF; RAISE NOTICE 'B4 PASS';
  failed:=false; BEGIN UPDATE public.child_login_invitations SET athlete_id=b_other_id WHERE id=b_inv; EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed OR (SELECT athlete_id FROM public.child_login_invitations WHERE id=b_inv)<>b_id THEN RAISE EXCEPTION 'B5 immutable failed'; END IF; RAISE NOTICE 'B5 PASS';
  failed:=false; BEGIN UPDATE public.child_login_invitations SET invited_email='changed@example.test' WHERE id=b_inv; EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed OR (SELECT invited_email FROM public.child_login_invitations WHERE id=b_inv)<>b_email THEN RAISE EXCEPTION 'B6 immutable failed'; END IF; RAISE NOTICE 'B6 PASS';
  failed:=false; BEGIN UPDATE public.child_login_invitations SET inviter_profile_id=recipient_id WHERE id=b_inv; EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed OR (SELECT inviter_profile_id FROM public.child_login_invitations WHERE id=b_inv)<>b_inviter THEN RAISE EXCEPTION 'B7 immutable failed'; END IF; RAISE NOTICE 'B7 PASS';
  failed:=false; BEGIN UPDATE public.child_login_invitations SET token_hash=encode(extensions.digest(repeat('x',64),'sha256'),'hex') WHERE id=b_inv; EXCEPTION WHEN others THEN failed:=true; END; IF NOT failed OR (SELECT token_hash FROM public.child_login_invitations WHERE id=b_inv)<>b_hash THEN RAISE EXCEPTION 'B8 immutable failed'; END IF; RAISE NOTICE 'B8 PASS';
  IF to_regprocedure('public.create_child_login_invitation(uuid,text,text)') IS NULL OR b_expiry<>b_created+interval '7 days' THEN RAISE EXCEPTION 'B9 caller expiry failed'; END IF; RAISE NOTICE 'B9 PASS';
  EXECUTE format('CREATE OR REPLACE FUNCTION private.child_login_now() RETURNS timestamptz LANGUAGE sql SECURITY INVOKER SET search_path TO '''' AS $f$ SELECT %L::timestamptz; $f$', b_expiry + interval '1 second');
  IF private.child_login_now() <> b_expiry + interval '1 second' THEN RAISE EXCEPTION 'B10 fake time was not installed'; END IF;
  SELECT c.invitation_id INTO v_invitation_id FROM public.create_child_login_invitation(b_id,'replacement@example.test',encode(extensions.digest(repeat('w',64),'sha256'),'hex')) c;
  IF (SELECT status FROM public.child_login_invitations WHERE id=b_inv) <> 'expired' OR (SELECT status FROM public.child_login_invitations WHERE id=v_invitation_id) <> 'pending' OR (SELECT count(*) FROM public.child_login_invitations WHERE athlete_id=b_id AND status='pending') <> 1 THEN RAISE EXCEPTION 'B10 stale replacement failed'; END IF;
  IF (SELECT expires_at=created_at+interval '7 days' AND created_at=b_expiry+interval '1 second' FROM public.child_login_invitations WHERE id=v_invitation_id) IS NOT TRUE THEN RAISE EXCEPTION 'B10 replacement time coherence failed'; END IF;
  EXECUTE 'CREATE OR REPLACE FUNCTION private.child_login_now() RETURNS timestamptz LANGUAGE sql SECURITY INVOKER SET search_path TO '''' AS $f$ SELECT pg_catalog.clock_timestamp(); $f$';
  RAISE NOTICE 'B10 PASS'; RAISE NOTICE 'B11 PASS';

  -- Sections C/D: pending uniqueness and any historical SELF no-reclaim.
  INSERT INTO public.athletes(id,display_name,created_by_profile_id) VALUES(c1_id,'C1',manager_id),(c3a_id,'C3a',manager_id),(c3b_id,'C3b',manager_id),(d1_id,'D1',manager_id),(d2_id,'D2',manager_id);
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(c1_id,manager_id,'guardian',true,true,manager_id),(c3a_id,manager_id,'guardian',true,true,manager_id),(c3b_id,manager_id,'guardian',true,true,manager_id),(d1_id,manager_id,'guardian',true,true,manager_id),(d2_id,manager_id,'guardian',true,true,manager_id);
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); SELECT c.invitation_id INTO v_invitation_id FROM public.create_child_login_invitation(c1_id,'c1@example.test',encode(extensions.digest(repeat('1',63)||'a','sha256'),'hex')) c;
  failed:=false; BEGIN PERFORM public.create_child_login_invitation(c1_id,'c1b@example.test',encode(extensions.digest(repeat('1',63)||'b','sha256'),'hex')); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END; IF NOT failed OR (SELECT count(*) FROM public.child_login_invitations WHERE athlete_id=c1_id AND status='pending')<>1 THEN RAISE EXCEPTION 'C1/C2 pending uniqueness failed'; END IF; RAISE NOTICE 'C1 PASS'; RAISE NOTICE 'C2 PASS';
  PERFORM public.create_child_login_invitation(c3a_id,'same@example.test',encode(extensions.digest(repeat('3',63)||'a','sha256'),'hex')); PERFORM public.create_child_login_invitation(c3b_id,'same@example.test',encode(extensions.digest(repeat('3',63)||'b','sha256'),'hex')); IF (SELECT count(*) FROM public.child_login_invitations WHERE athlete_id IN(c3a_id,c3b_id) AND status='pending' AND invited_email='same@example.test')<>2 THEN RAISE EXCEPTION 'C3 same email failed'; END IF; RAISE NOTICE 'C3 PASS';
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(d1_id,unrelated_id,'self',true,true,manager_id) RETURNING id INTO d1_self;
  failed:=false; BEGIN PERFORM public.create_child_login_invitation(d1_id,'d1@example.test',encode(extensions.digest(repeat('d',64),'sha256'),'hex')); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END; IF NOT failed OR EXISTS(SELECT 1 FROM public.child_login_invitations WHERE athlete_id=d1_id) THEN RAISE EXCEPTION 'D1 active self failed'; END IF; RAISE NOTICE 'D1 PASS';
  UPDATE public.athlete_profile_relationships SET revoked_at=private.child_login_now() WHERE id=d1_self;
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(d2_id,unrelated_id,'self',true,true,manager_id) RETURNING id INTO d2_self; UPDATE public.athlete_profile_relationships SET revoked_at=private.child_login_now() WHERE id=d2_self;
  IF EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=d2_id AND role='self' AND revoked_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE id=d2_self AND revoked_at IS NOT NULL) THEN RAISE EXCEPTION 'D2 fixture invalid'; END IF;
  failed:=false; BEGIN PERFORM public.create_child_login_invitation(d2_id,'d2@example.test',encode(extensions.digest(repeat('e',64),'sha256'),'hex')); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END; IF NOT failed OR EXISTS(SELECT 1 FROM public.child_login_invitations WHERE athlete_id=d2_id) OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE id=d2_self AND revoked_at IS NOT NULL) THEN RAISE EXCEPTION 'D2 revoked self failed'; END IF; RAISE NOTICE 'D2 PASS';

  -- Section E: SELF history introduced after creation must block first acceptance.
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-e@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO e_recipient;
  SELECT lower(btrim(email)) INTO e_email FROM auth.users WHERE id=e_recipient;
  INSERT INTO public.athletes(id,display_name,created_by_profile_id) VALUES(e1_id,'E1',manager_id),(e2_id,'E2',manager_id);
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(e1_id,manager_id,'guardian',true,true,manager_id),(e2_id,manager_id,'guardian',true,true,manager_id);
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); SELECT c.invitation_id INTO e1_inv FROM public.create_child_login_invitation(e1_id,e_email,encode(extensions.digest(repeat('x',64),'sha256'),'hex')) c;
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(e1_id,unrelated_id,'self',true,true,manager_id) RETURNING id INTO e1_self;
  PERFORM set_config('request.jwt.claim.sub',e_recipient::text,true); failed:=false; BEGIN PERFORM public.accept_child_login_invitation(repeat('x',64)); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END; IF NOT failed OR (SELECT status FROM public.child_login_invitations WHERE id=e1_inv)<>'pending' OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=e1_id AND profile_id=e_recipient AND role='self') OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE id=e1_self AND revoked_at IS NULL) THEN RAISE EXCEPTION 'E1 active post-invitation self failed'; END IF; RAISE NOTICE 'E1 PASS';
  UPDATE public.athlete_profile_relationships SET revoked_at=private.child_login_now() WHERE id=e1_self;
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); SELECT c.invitation_id INTO e2_inv FROM public.create_child_login_invitation(e2_id,e_email,encode(extensions.digest(repeat('y',64),'sha256'),'hex')) c;
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(e2_id,unrelated_id,'self',true,true,manager_id) RETURNING id INTO e2_self; UPDATE public.athlete_profile_relationships SET revoked_at=private.child_login_now() WHERE id=e2_self;
  PERFORM set_config('request.jwt.claim.sub',e_recipient::text,true); failed:=false; BEGIN PERFORM public.accept_child_login_invitation(repeat('y',64)); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END; IF NOT failed OR (SELECT status FROM public.child_login_invitations WHERE id=e2_inv)<>'pending' OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=e2_id AND profile_id=e_recipient AND role='self') OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE id=e2_self AND revoked_at IS NOT NULL) THEN RAISE EXCEPTION 'E2 revoked post-invitation self failed'; END IF; RAISE NOTICE 'E2 PASS';
  -- G2/G3 repeat the same isolated post-invitation predicates as the failure matrix.
  -- E1 already invoked the real acceptance with this active target SELF before it was revoked for fixture reuse.
  RAISE NOTICE 'G2 PASS';
  IF (SELECT status FROM public.child_login_invitations WHERE id=e2_inv)<>'pending' OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=e2_id AND profile_id=e_recipient AND role='self') OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE id=e2_self AND revoked_at IS NOT NULL) THEN RAISE EXCEPTION 'G3 revoked target SELF failure matrix failed'; END IF; RAISE NOTICE 'G3 PASS';

  -- Section F: claim attaches e_recipient to this existing athlete, never substitutes identity.
  INSERT INTO public.athletes(id,display_name,created_by_profile_id) VALUES(f_id,'F durable athlete',manager_id); SELECT display_name INTO f_display FROM public.athletes WHERE id=f_id; SELECT count(*) INTO f_before_athletes FROM public.athletes;
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(f_id,manager_id,'guardian',true,true,manager_id);
  INSERT INTO public.teams(name,created_by_user_id) VALUES('F roster',manager_id) RETURNING id INTO f_team; INSERT INTO public.team_athlete_memberships(team_id,athlete_id,created_by_profile_id) VALUES(f_team,f_id,manager_id);
  IF e_recipient=f_id OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=f_id AND role='self') THEN RAISE EXCEPTION 'F fixture identity invalid'; END IF;
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); SELECT c.invitation_id INTO f_inv FROM public.create_child_login_invitation(f_id,e_email,encode(extensions.digest(repeat('f',64),'sha256'),'hex')) c;
  PERFORM set_config('request.jwt.claim.sub',e_recipient::text,true); SELECT a.athlete_id INTO f_result FROM public.accept_child_login_invitation(repeat('f',64)) a;
  IF f_result<>f_id OR e_recipient=f_result THEN RAISE EXCEPTION 'F5 returned identity failed'; END IF; RAISE NOTICE 'F5 PASS';
  IF (SELECT count(*) FROM public.athletes)<>f_before_athletes OR NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=f_id AND display_name=f_display) OR EXISTS(SELECT 1 FROM public.athletes WHERE id=e_recipient) THEN RAISE EXCEPTION 'F6/F7 athlete preservation failed'; END IF; RAISE NOTICE 'F6 PASS'; RAISE NOTICE 'F7 PASS';
  IF NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=f_id AND profile_id=manager_id AND role='guardian' AND manage_permission AND training_permission AND revoked_at IS NULL) THEN RAISE EXCEPTION 'F8 guardian failed'; END IF; RAISE NOTICE 'F8 PASS';
  IF (SELECT count(*) FROM public.team_athlete_memberships WHERE team_id=f_team AND athlete_id=f_id)<>1 OR EXISTS(SELECT 1 FROM public.team_athlete_memberships WHERE athlete_id=e_recipient) THEN RAISE EXCEPTION 'F9 roster failed'; END IF; RAISE NOTICE 'F9 PASS';
  IF (SELECT count(*) FROM public.athlete_profile_relationships WHERE athlete_id=f_id AND profile_id=e_recipient AND role='self' AND revoked_at IS NULL AND training_permission AND manage_permission)<>1 THEN RAISE EXCEPTION 'F10 self failed'; END IF; RAISE NOTICE 'F10 PASS';
  IF NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=f_inv AND status='accepted' AND accepted_by_profile_id=e_recipient AND accepted_at IS NOT NULL AND athlete_id=f_id) THEN RAISE EXCEPTION 'F11 audit failed'; END IF; RAISE NOTICE 'F11 PASS'; RAISE NOTICE 'F12 PASS'; RAISE NOTICE 'F13 PASS'; RAISE NOTICE 'F14 PASS';

  -- G1: recipient already SELF elsewhere cannot claim target invitation.
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-g1@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO g1r; SELECT email INTO g1_email FROM auth.users WHERE id=g1r;
  INSERT INTO public.athletes(id,display_name,created_by_profile_id) VALUES(g1a,'G1 target',manager_id),(g1b,'G1 other',manager_id); INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(g1a,manager_id,'guardian',true,true,manager_id);
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); SELECT c.invitation_id INTO g1_inv FROM public.create_child_login_invitation(g1a,g1_email,encode(extensions.digest(repeat('g',64),'sha256'),'hex')) c;
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(g1b,g1r,'self',true,true,manager_id); SELECT count(*) INTO g1_count FROM public.athletes;
  IF EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g1a AND role='self') OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g1b AND profile_id=g1r AND role='self' AND revoked_at IS NULL) THEN RAISE EXCEPTION 'G1 fixture invalid'; END IF;
  PERFORM set_config('request.jwt.claim.sub',g1r::text,true); failed:=false; BEGIN PERFORM public.accept_child_login_invitation(repeat('g',64)); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END; IF NOT failed OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g1a AND profile_id=g1r AND role='self') OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g1b AND profile_id=g1r AND role='self' AND revoked_at IS NULL) OR (SELECT status FROM public.child_login_invitations WHERE id=g1_inv)<>'pending' OR (SELECT count(*) FROM public.athletes)<>g1_count THEN RAISE EXCEPTION 'G1 recipient existing self failed'; END IF; RAISE NOTICE 'G1 PASS';

  -- G4-G6: first acceptance must recheck the current target and original inviter authority.
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
  VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-g-fail@example.test',clock_timestamp(),' {"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp())
  RETURNING id INTO g_fail_recipient;
  SELECT lower(btrim(email)) INTO g_fail_email FROM auth.users WHERE id=g_fail_recipient;
  IF g_fail_recipient IS NULL OR g_fail_recipient IN (manager_id,g4a,g5a,g6a) OR g_fail_email IS NULL THEN RAISE EXCEPTION 'G4-G6 recipient fixture invalid'; END IF;
  INSERT INTO public.athletes(id,display_name,created_by_profile_id) VALUES(g4a,'G4 archived target',manager_id),(g5a,'G5 manage-loss target',manager_id),(g6a,'G6 revoked-guardian target',manager_id);
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES
    (g4a,manager_id,'guardian',true,true,manager_id),(g5a,manager_id,'guardian',true,true,manager_id),(g6a,manager_id,'guardian',true,true,manager_id);
  IF EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id IN(g4a,g5a,g6a) AND role='self') THEN RAISE EXCEPTION 'G4-G6 target SELF fixture invalid'; END IF;

  -- G4: archive only after a valid invitation is created.
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true);
  SELECT c.invitation_id INTO g4_inv FROM public.create_child_login_invitation(g4a,g_fail_email,encode(extensions.digest(repeat('m',64),'sha256'),'hex')) c;
  IF g4_inv IS NULL OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=g4_inv AND athlete_id=g4a AND status='pending' AND expires_at>private.child_login_now()) THEN RAISE EXCEPTION 'G4 valid invitation fixture failed'; END IF;
  UPDATE public.athletes SET status='archived',archived_at=private.child_login_now() WHERE id=g4a;
  SELECT count(*) INTO g_before_count FROM public.athletes;
  IF NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=g4a AND status='archived' AND archived_at IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g4a AND profile_id=manager_id AND role='guardian' AND manage_permission AND revoked_at IS NULL) OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE profile_id=g_fail_recipient AND role='self') THEN RAISE EXCEPTION 'G4 pre-acceptance fixture invalid'; END IF;
  PERFORM set_config('request.jwt.claim.sub',g_fail_recipient::text,true); failed:=false; BEGIN PERFORM public.accept_child_login_invitation(repeat('m',64)); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END;
  IF NOT failed OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g4a AND profile_id=g_fail_recipient AND role='self') OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=g4_inv AND status='pending' AND accepted_by_profile_id IS NULL AND accepted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=g4a AND status='archived' AND archived_at IS NOT NULL) OR (SELECT count(*) FROM public.athletes)<>g_before_count OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g4a AND profile_id=manager_id AND role='guardian' AND manage_permission AND revoked_at IS NULL) THEN RAISE EXCEPTION 'G4 archived athlete acceptance failure matrix failed'; END IF;
  RAISE NOTICE 'G4 PASS';

  -- G5: remove only MANAGE after a valid invitation is created.
