  SELECT c.invitation_id INTO g5_inv FROM public.create_child_login_invitation(g5a,g_fail_email,encode(extensions.digest(repeat('n',64),'sha256'),'hex')) c;
  IF g5_inv IS NULL OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=g5_inv AND athlete_id=g5a AND status='pending' AND expires_at>private.child_login_now()) THEN RAISE EXCEPTION 'G5 valid invitation fixture failed'; END IF;
  UPDATE public.athlete_profile_relationships SET manage_permission=false WHERE athlete_id=g5a AND profile_id=manager_id AND role='guardian' AND revoked_at IS NULL;
  SELECT count(*) INTO g_before_count FROM public.athletes;
  IF NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=g5a AND status='active') OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g5a AND profile_id=manager_id AND role='guardian' AND NOT manage_permission AND revoked_at IS NULL) OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g5a AND role='self') OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE profile_id=g_fail_recipient AND role='self') THEN RAISE EXCEPTION 'G5 pre-acceptance fixture invalid'; END IF;
  PERFORM set_config('request.jwt.claim.sub',g_fail_recipient::text,true); failed:=false; BEGIN PERFORM public.accept_child_login_invitation(repeat('n',64)); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END;
  IF NOT failed OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g5a AND profile_id=g_fail_recipient AND role='self') OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=g5_inv AND status='pending' AND accepted_by_profile_id IS NULL AND accepted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=g5a AND status='active') OR (SELECT count(*) FROM public.athletes)<>g_before_count OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g5a AND profile_id=manager_id AND role='guardian' AND NOT manage_permission AND revoked_at IS NULL) THEN RAISE EXCEPTION 'G5 inviter MANAGE loss acceptance failure matrix failed'; END IF;
  RAISE NOTICE 'G5 PASS';

  -- G6: revoke only the original guardian relation after a valid invitation is created.
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true);
  SELECT c.invitation_id INTO g6_inv FROM public.create_child_login_invitation(g6a,g_fail_email,encode(extensions.digest(repeat('o',64),'sha256'),'hex')) c;
  IF g6_inv IS NULL OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=g6_inv AND athlete_id=g6a AND status='pending' AND expires_at>private.child_login_now()) THEN RAISE EXCEPTION 'G6 valid invitation fixture failed'; END IF;
  UPDATE public.athlete_profile_relationships SET revoked_at=private.child_login_now() WHERE athlete_id=g6a AND profile_id=manager_id AND role='guardian' AND revoked_at IS NULL;
  SELECT count(*) INTO g_before_count FROM public.athletes;
  IF NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=g6a AND status='active') OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g6a AND profile_id=manager_id AND role='guardian' AND manage_permission AND revoked_at IS NOT NULL) OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g6a AND role='self') OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE profile_id=g_fail_recipient AND role='self') THEN RAISE EXCEPTION 'G6 pre-acceptance fixture invalid'; END IF;
  PERFORM set_config('request.jwt.claim.sub',g_fail_recipient::text,true); failed:=false; BEGIN PERFORM public.accept_child_login_invitation(repeat('o',64)); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END;
  IF NOT failed OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g6a AND profile_id=g_fail_recipient AND role='self') OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=g6_inv AND status='pending' AND accepted_by_profile_id IS NULL AND accepted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=g6a AND status='active') OR (SELECT count(*) FROM public.athletes)<>g_before_count OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g6a AND profile_id=manager_id AND role='guardian' AND manage_permission AND revoked_at IS NOT NULL) THEN RAISE EXCEPTION 'G6 revoked guardian acceptance failure matrix failed'; END IF;
  RAISE NOTICE 'G6 PASS';

  -- G7: only a real revoke RPC may put a valid invitation into the revoked lifecycle state.
  INSERT INTO public.athletes(id,display_name,created_by_profile_id) VALUES(g7a,'G7 revoked invitation target',manager_id);
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(g7a,manager_id,'guardian',true,true,manager_id);
  IF NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=g7a AND status='active') OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g7a AND role='self') OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE profile_id=g_fail_recipient AND role='self') OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g7a AND profile_id=manager_id AND role='guardian' AND manage_permission AND revoked_at IS NULL) THEN RAISE EXCEPTION 'G7 pre-invitation fixture invalid'; END IF;
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true);
  SELECT c.invitation_id INTO g7_inv FROM public.create_child_login_invitation(g7a,g_fail_email,encode(extensions.digest(repeat('p',64),'sha256'),'hex')) c;
  SELECT created_at,expires_at,invited_email,token_hash INTO g7_created,g7_expires,g7_email,g7_hash FROM public.child_login_invitations WHERE id=g7_inv;
  IF g7_inv IS NULL OR g7_expires<>g7_created+interval '7 days' OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=g7_inv AND athlete_id=g7a AND inviter_profile_id=manager_id AND status='pending' AND expires_at>private.child_login_now()) THEN RAISE EXCEPTION 'G7 valid invitation fixture failed'; END IF;
  PERFORM public.revoke_child_login_invitation(g7_inv);
  IF NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=g7_inv AND athlete_id=g7a AND invited_email=g7_email AND inviter_profile_id=manager_id AND token_hash=g7_hash AND created_at=g7_created AND expires_at=g7_expires AND status='revoked' AND revoked_by_profile_id=manager_id AND revoked_at IS NOT NULL AND accepted_by_profile_id IS NULL AND accepted_at IS NULL) THEN RAISE EXCEPTION 'G7 real revoke lifecycle or immutable identity failed'; END IF;
  SELECT count(*) INTO g_before_count FROM public.athletes;
  IF NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=g7a AND status='active') OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g7a AND role='self') OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE profile_id=g_fail_recipient AND role='self') OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g7a AND profile_id=manager_id AND role='guardian' AND manage_permission AND revoked_at IS NULL) THEN RAISE EXCEPTION 'G7 pre-acceptance fixture invalid'; END IF;
  PERFORM set_config('request.jwt.claim.sub',g_fail_recipient::text,true); failed:=false; BEGIN PERFORM public.accept_child_login_invitation(repeat('p',64)); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END;
  IF NOT failed OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g7a AND profile_id=g_fail_recipient AND role='self') OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=g7_inv AND athlete_id=g7a AND invited_email=g7_email AND inviter_profile_id=manager_id AND token_hash=g7_hash AND created_at=g7_created AND expires_at=g7_expires AND status='revoked' AND revoked_by_profile_id=manager_id AND revoked_at IS NOT NULL AND accepted_by_profile_id IS NULL AND accepted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=g7a AND status='active') OR (SELECT count(*) FROM public.athletes)<>g_before_count OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g7a AND profile_id=manager_id AND role='guardian' AND manage_permission AND revoked_at IS NULL) THEN RAISE EXCEPTION 'G7 revoked invitation acceptance failure matrix failed'; END IF;
  RAISE NOTICE 'G7 PASS';

  -- G8: advance only the validator clock beyond expiry; invitation identity stays immutable.
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true);
  INSERT INTO public.athletes(id,display_name,created_by_profile_id) VALUES(g8a,'G8 expired invitation target',manager_id);
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(g8a,manager_id,'guardian',true,true,manager_id);
  IF NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=g8a AND status='active') OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g8a AND role='self') OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE profile_id=g_fail_recipient AND role='self') OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g8a AND profile_id=manager_id AND role='guardian' AND manage_permission AND revoked_at IS NULL) THEN RAISE EXCEPTION 'G8 pre-invitation fixture invalid'; END IF;
  SELECT c.invitation_id INTO g8_inv FROM public.create_child_login_invitation(g8a,g_fail_email,encode(extensions.digest(repeat('r',64),'sha256'),'hex')) c;
  SELECT created_at,expires_at,status INTO g8_created,g8_expires,g8_status FROM public.child_login_invitations WHERE id=g8_inv;
  IF g8_inv IS NULL OR g8_status<>'pending' OR g8_expires<>g8_created+interval '7 days' OR g8_expires<=private.child_login_now() THEN RAISE EXCEPTION 'G8 valid invitation fixture failed'; END IF;
  EXECUTE format('CREATE OR REPLACE FUNCTION private.child_login_now() RETURNS timestamptz LANGUAGE sql SECURITY INVOKER SET search_path TO '''' AS $f$ SELECT %L::timestamptz; $f$', g8_expires + interval '1 second');
  IF private.child_login_now()<>g8_expires+interval '1 second' THEN RAISE EXCEPTION 'G8 controlled time was not installed'; END IF;
  SELECT count(*) INTO g_before_count FROM public.athletes;
  IF NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=g8a AND status='active') OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g8a AND role='self') OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE profile_id=g_fail_recipient AND role='self') OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g8a AND profile_id=manager_id AND role='guardian' AND manage_permission AND revoked_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=g8_inv AND created_at=g8_created AND expires_at=g8_expires AND status='pending') THEN RAISE EXCEPTION 'G8 pre-acceptance fixture invalid'; END IF;
  PERFORM set_config('request.jwt.claim.sub',g_fail_recipient::text,true); failed:=false; BEGIN PERFORM public.accept_child_login_invitation(repeat('r',64)); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END;
  IF NOT failed OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g8a AND profile_id=g_fail_recipient AND role='self') OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=g8_inv AND created_at=g8_created AND expires_at=g8_expires AND status='pending' AND accepted_by_profile_id IS NULL AND accepted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.athletes WHERE id=g8a AND status='active') OR (SELECT count(*) FROM public.athletes)<>g_before_count OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=g8a AND profile_id=manager_id AND role='guardian' AND manage_permission AND revoked_at IS NULL) THEN RAISE EXCEPTION 'G8 expired invitation acceptance failure matrix failed'; END IF;
  EXECUTE 'CREATE OR REPLACE FUNCTION private.child_login_now() RETURNS timestamptz LANGUAGE sql SECURITY INVOKER SET search_path TO '''' AS $f$ SELECT pg_catalog.clock_timestamp(); $f$';
  IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='private' AND p.proname='child_login_now' AND p.pronargs=0 AND NOT p.prosecdef AND coalesce(p.proconfig,ARRAY[]::text[]) @> ARRAY['search_path=""']::text[] AND pg_get_functiondef(p.oid) LIKE '%SELECT pg_catalog.clock_timestamp();%' AND NOT has_function_privilege('public',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE')) THEN RAISE EXCEPTION 'G8 child_login_now restoration or ACL failed'; END IF;
