  -- H2: accepted retry is not a second first-acceptance authority check.
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-h2@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO h2r;
