  IF NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=h2a AND profile_id=manager_id AND role='guardian' AND manage_permission AND revoked_at IS NOT NULL) THEN RAISE EXCEPTION 'H2 revocation fixture failed'; END IF;
  PERFORM set_config('request.jwt.claim.sub',h2r::text,true); SELECT a.athlete_id INTO v_result FROM public.accept_child_login_invitation(repeat('t',64)) a;
