  EXECUTE format('CREATE OR REPLACE FUNCTION private.child_login_now() RETURNS timestamptz LANGUAGE sql SECURITY INVOKER SET search_path TO '''' AS $f$ SELECT %L::timestamptz; $f$', h8_expires + interval '1 second');
  IF private.child_login_now()<>h8_expires+interval '1 second' THEN RAISE EXCEPTION 'H8 controlled time was not installed'; END IF;
  PERFORM set_config('request.jwt.claim.sub',h8r::text,true); SELECT a.athlete_id INTO v_result FROM public.accept_child_login_invitation(repeat('z',64)) a;
  IF v_result<>h8a OR (SELECT count(*) FROM public.athletes)<>g_before_count OR (SELECT count(*) FROM public.athlete_profile_relationships WHERE athlete_id=h8a AND profile_id=h8r AND role='self' AND revoked_at IS NULL AND training_permission AND manage_permission)<>1 OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=h8_inv AND status='accepted' AND accepted_by_profile_id=h8r AND accepted_at=h_accepted_at AND created_at=h8_created AND expires_at=h8_expires AND athlete_id=h8a) THEN RAISE EXCEPTION 'H8 accepted retry after expiry failed'; END IF;
  EXECUTE 'CREATE OR REPLACE FUNCTION private.child_login_now() RETURNS timestamptz LANGUAGE sql SECURITY INVOKER SET search_path TO '''' AS $f$ SELECT pg_catalog.clock_timestamp(); $f$';
  IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='private' AND p.proname='child_login_now' AND p.pronargs=0 AND NOT p.prosecdef AND coalesce(p.proconfig,ARRAY[]::text[]) @> ARRAY['search_path=""']::text[] AND pg_get_functiondef(p.oid) LIKE '%SELECT pg_catalog.clock_timestamp();%' AND NOT has_function_privilege('public',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE')) THEN RAISE EXCEPTION 'H8 child_login_now restoration or ACL failed'; END IF;
  RAISE NOTICE 'H8 PASS'; RAISE NOTICE 'SECTION H PASS';

  -- Section I: summary disclosure is gated exclusively by confirmed canonical auth.users.email.
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-i-good@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO i_good;
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-i-wrong@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO i_wrong;
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-i-unconfirmed@example.test',NULL,'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO i_unconfirmed;
  SELECT lower(btrim(email)) INTO i_email FROM auth.users WHERE id=i_good;
  SELECT lower(btrim(email)) INTO i_wrong_email FROM auth.users WHERE id=i_wrong;
  SELECT lower(btrim(email)) INTO i_unconfirmed_email FROM auth.users WHERE id=i_unconfirmed;
  INSERT INTO public.athletes(id,display_name,created_by_profile_id) VALUES(i1a,i_expected_display,manager_id),(i2a,'I unconfirmed private child',manager_id);
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(i1a,manager_id,'guardian',true,true,manager_id),(i2a,manager_id,'guardian',true,true,manager_id);
  IF i_good=i1a OR i_wrong IN(i_good,i1a) OR i_unconfirmed IN(i_good,i_wrong,i1a) OR EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=i1a AND role='self') THEN RAISE EXCEPTION 'I fixture identities invalid'; END IF;
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); SELECT c.invitation_id INTO i_inv FROM public.create_child_login_invitation(i1a,i_email,encode(extensions.digest(repeat('A',64),'sha256'),'hex')) c;
  SELECT c.invitation_id INTO i2_inv FROM public.create_child_login_invitation(i2a,i_unconfirmed_email,encode(extensions.digest(repeat('B',64),'sha256'),'hex')) c;
  IF i_inv IS NULL OR i2_inv IS NULL OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=i_inv AND athlete_id=i1a AND invited_email=i_email AND status='pending' AND expires_at>private.child_login_now()) THEN RAISE EXCEPTION 'I valid invitation fixture failed'; END IF;

  -- I1: confirmed but wrong authoritative email gets no row from a valid token.
  PERFORM set_config('request.jwt.claim.sub',i_wrong::text,true); SELECT count(*) INTO i_count FROM public.get_child_login_invitation_summary(repeat('A',64));
  IF i_count<>0 OR i_wrong_email=i_email THEN RAISE EXCEPTION 'I1 wrong authenticated email disclosed summary'; END IF;
  RAISE NOTICE 'I1 PASS';

  -- I2: exact email without confirmation is still not a disclosure credential.
  PERFORM set_config('request.jwt.claim.sub',i_unconfirmed::text,true); SELECT count(*) INTO i_count FROM public.get_child_login_invitation_summary(repeat('B',64));
  IF i_count<>0 OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=i_unconfirmed AND lower(btrim(email))=i_unconfirmed_email AND email_confirmed_at IS NULL) THEN RAISE EXCEPTION 'I2 unconfirmed recipient disclosed summary'; END IF;
  RAISE NOTICE 'I2 PASS';

  -- I3: exact confirmed recipient receives only the reviewed minimal summary.
  PERFORM set_config('request.jwt.claim.sub',i_good::text,true); SELECT count(*),max(s.athlete_display_name),max(s.expires_at),max(s.invitation_status::text) INTO i_count,i_name,i_exp,i_status FROM public.get_child_login_invitation_summary(repeat('A',64)) s;
  IF i_count<>1 OR i_name<>i_expected_display OR i_exp<>(SELECT expires_at FROM public.child_login_invitations WHERE id=i_inv) OR i_status<>(SELECT status::text FROM public.child_login_invitations WHERE id=i_inv) THEN RAISE EXCEPTION 'I3 exact recipient minimal summary failed'; END IF;
  RAISE NOTICE 'I3 PASS';

  -- I4: lower/btrim equivalence passes; a genuinely different authoritative email fails.
  UPDATE auth.users SET email=upper(i_email),updated_at=private.child_login_now() WHERE id=i_good;
  PERFORM set_config('request.jwt.claim.sub',i_good::text,true); SELECT count(*) INTO i_count FROM public.get_child_login_invitation_summary(repeat('A',64));
  IF i_count<>1 OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=i_good AND lower(btrim(email))=i_email AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'I4 normalization-equivalent email failed'; END IF;
  UPDATE auth.users SET email=v_marker||'-i-different@example.test',updated_at=private.child_login_now() WHERE id=i_good;
  SELECT count(*) INTO i_count FROM public.get_child_login_invitation_summary(repeat('A',64));
  IF i_count<>0 THEN RAISE EXCEPTION 'I4 genuinely different email disclosed summary'; END IF;
  UPDATE auth.users SET email=i_email,updated_at=private.child_login_now() WHERE id=i_good;
  RAISE NOTICE 'I4 PASS';

  -- I5: matching metadata cannot substitute for the authoritative auth.users.email gate.
  UPDATE auth.users SET raw_user_meta_data=jsonb_build_object('email',i_email),updated_at=private.child_login_now() WHERE id=i_wrong;
  PERFORM set_config('request.jwt.claim.sub',i_wrong::text,true); SELECT count(*) INTO i_count FROM public.get_child_login_invitation_summary(repeat('A',64));
  IF i_count<>0 OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=i_wrong AND raw_user_meta_data->>'email'=i_email AND lower(btrim(email))<>i_email) OR position('SELECT u.email,u.email_confirmed_at' in pg_get_functiondef('public.get_child_login_invitation_summary(text)'::regprocedure))=0 THEN RAISE EXCEPTION 'I5 metadata substituted for authoritative email'; END IF;
  RAISE NOTICE 'I5 PASS';

  -- I6: valid-unknown and malformed tokens return no identity-bearing summary.
  SELECT count(*) INTO i_count FROM public.get_child_login_invitation_summary(repeat('C',64));
  IF i_count<>0 THEN RAISE EXCEPTION 'I6 unknown token disclosed summary'; END IF;
  SELECT count(*) INTO i_count FROM public.get_child_login_invitation_summary('not-a-valid-token');
  IF i_count<>0 THEN RAISE EXCEPTION 'I6 malformed token disclosed summary'; END IF;
  RAISE NOTICE 'I6 PASS';

  -- I7: a successful summary call is strictly read-only.
  PERFORM set_config('request.jwt.claim.sub',i_good::text,true);
  SELECT to_jsonb(i) INTO i_inv_before FROM public.child_login_invitations i WHERE i.id=i_inv;
  SELECT to_jsonb(a) INTO i_athlete_before FROM public.athletes a WHERE a.id=i1a;
  SELECT count(*) INTO i_rel_before FROM public.athlete_profile_relationships WHERE athlete_id=i1a;
  PERFORM * FROM public.get_child_login_invitation_summary(repeat('A',64));
  IF (SELECT to_jsonb(i) FROM public.child_login_invitations i WHERE i.id=i_inv)<>i_inv_before OR (SELECT to_jsonb(a) FROM public.athletes a WHERE a.id=i1a)<>i_athlete_before OR (SELECT count(*) FROM public.athlete_profile_relationships WHERE athlete_id=i1a)<>i_rel_before THEN RAISE EXCEPTION 'I7 summary mutated invitation, athlete, or relationships'; END IF;
  RAISE NOTICE 'I7 PASS';

  -- I8: exact three-column contract and authorized/unauthorized cardinality are pinned.
  IF pg_get_function_result('public.get_child_login_invitation_summary(text)'::regprocedure)<>'TABLE(athlete_display_name text, expires_at timestamp with time zone, invitation_status team_invitation_status)' THEN RAISE EXCEPTION 'I8 summary return descriptor changed'; END IF;
  PERFORM set_config('request.jwt.claim.sub',i_good::text,true); SELECT count(*) INTO i_count FROM public.get_child_login_invitation_summary(repeat('A',64)); IF i_count<>1 THEN RAISE EXCEPTION 'I8 authorized summary cardinality failed'; END IF;
  PERFORM set_config('request.jwt.claim.sub',i_wrong::text,true); SELECT count(*) INTO i_count FROM public.get_child_login_invitation_summary(repeat('A',64)); IF i_count<>0 THEN RAISE EXCEPTION 'I8 unauthorized summary cardinality failed'; END IF;
  RAISE NOTICE 'I8 PASS'; RAISE NOTICE 'SECTION I PASS';

  -- Section J: revocation is an exact active guardian+MANAGE lifecycle action.
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-j-view@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO j_view;
