  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-j-self@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO j_self;
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-j-staff@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO j_staff;
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-j-wrong@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO j_wrong;
  INSERT INTO public.athletes(id,display_name,created_by_profile_id) VALUES(j1a,'J1',manager_id),(j2a,'J2',manager_id),(j3a,'J3',manager_id),(j4a,'J4',manager_id),(j4b,'J4 other',manager_id),(j4c,'J4 staff',manager_id),(j4d,'J4 wrong guardian',manager_id),(j6a,'J6',manager_id),(j7a,'J7',manager_id),(j8a,'J8a',manager_id),(j8b,'J8b',manager_id);
