  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true);
  SELECT c.invitation_id INTO j1_inv FROM public.create_child_login_invitation(j1a,'j1@example.test',encode(extensions.digest(repeat('D',64),'sha256'),'hex')) c;
  SELECT c.invitation_id INTO j2_inv FROM public.create_child_login_invitation(j2a,'j2@example.test',encode(extensions.digest(repeat('E',64),'sha256'),'hex')) c;
  SELECT c.invitation_id INTO j3_inv FROM public.create_child_login_invitation(j3a,'j3@example.test',encode(extensions.digest(repeat('F',64),'sha256'),'hex')) c;
  SELECT c.invitation_id INTO j4_inv FROM public.create_child_login_invitation(j4a,'j4@example.test',encode(extensions.digest(repeat('G',64),'sha256'),'hex')) c;
  SELECT c.invitation_id INTO j7_inv FROM public.create_child_login_invitation(j7a,'j7@example.test',encode(extensions.digest(repeat('H',64),'sha256'),'hex')) c;
  SELECT c.invitation_id INTO j8_inv_a FROM public.create_child_login_invitation(j8a,'j8a@example.test',encode(extensions.digest(repeat('I',64),'sha256'),'hex')) c;
  SELECT c.invitation_id INTO j8_inv_b FROM public.create_child_login_invitation(j8b,'j8b@example.test',encode(extensions.digest(repeat('J',64),'sha256'),'hex')) c;
  IF j1_inv IS NULL OR j2_inv IS NULL OR j3_inv IS NULL OR j4_inv IS NULL OR j7_inv IS NULL OR j8_inv_a IS NULL OR j8_inv_b IS NULL THEN RAISE EXCEPTION 'J pending fixtures failed'; END IF;
  INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(j4a,j_self,'self',true,true,manager_id);
  SELECT count(*) INTO j_before_count FROM public.athletes;
