  PERFORM set_config('request.jwt.claim.sub',j_view::text,true); failed:=false; BEGIN PERFORM public.revoke_child_login_invitation(j2_inv); EXCEPTION WHEN SQLSTATE '42501' THEN failed:=true; END; IF NOT failed OR (SELECT status FROM public.child_login_invitations WHERE id=j2_inv)<>'pending' THEN RAISE EXCEPTION 'J2 view-only revoke failed'; END IF; RAISE NOTICE 'J2 PASS';
  PERFORM set_config('request.jwt.claim.sub',j_revoked::text,true); failed:=false; BEGIN PERFORM public.revoke_child_login_invitation(j3_inv); EXCEPTION WHEN SQLSTATE '42501' THEN failed:=true; END; IF NOT failed OR (SELECT status FROM public.child_login_invitations WHERE id=j3_inv)<>'pending' THEN RAISE EXCEPTION 'J3 revoked guardian revoke failed'; END IF; RAISE NOTICE 'J3 PASS';
  PERFORM set_config('request.jwt.claim.sub',j_self::text,true); failed:=false; BEGIN PERFORM public.revoke_child_login_invitation(j4_inv); EXCEPTION WHEN SQLSTATE '42501' THEN failed:=true; END; IF NOT failed OR (SELECT status FROM public.child_login_invitations WHERE id=j4_inv)<>'pending' THEN RAISE EXCEPTION 'J4 SELF substitution failed'; END IF;
  PERFORM set_config('request.jwt.claim.sub',j_staff::text,true); failed:=false; BEGIN PERFORM public.revoke_child_login_invitation(j4_inv); EXCEPTION WHEN SQLSTATE '42501' THEN failed:=true; END; IF NOT failed OR (SELECT status FROM public.child_login_invitations WHERE id=j4_inv)<>'pending' THEN RAISE EXCEPTION 'J4 staff substitution failed'; END IF;
  PERFORM set_config('request.jwt.claim.sub',j_wrong::text,true); failed:=false; BEGIN PERFORM public.revoke_child_login_invitation(j4_inv); EXCEPTION WHEN SQLSTATE '42501' THEN failed:=true; END; IF NOT failed OR (SELECT status FROM public.child_login_invitations WHERE id=j4_inv)<>'pending' THEN RAISE EXCEPTION 'J4 wrong-athlete guardian substitution failed'; END IF; RAISE NOTICE 'J4 PASS';
  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); failed:=false; BEGIN PERFORM public.revoke_child_login_invitation(gen_random_uuid()); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END; IF NOT failed OR (SELECT status FROM public.child_login_invitations WHERE id=j4_inv)<>'pending' THEN RAISE EXCEPTION 'J5 unknown invitation failed'; END IF; RAISE NOTICE 'J5 PASS';
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-j6@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO j6r; SELECT lower(btrim(email)) INTO j6_email FROM auth.users WHERE id=j6r;
  SELECT c.invitation_id INTO j6_inv FROM public.create_child_login_invitation(j6a,j6_email,encode(extensions.digest(repeat('K',64),'sha256'),'hex')) c; PERFORM set_config('request.jwt.claim.sub',j6r::text,true); SELECT a.athlete_id INTO v_result FROM public.accept_child_login_invitation(repeat('K',64)) a; SELECT accepted_at INTO j6_accepted FROM public.child_login_invitations WHERE id=j6_inv; PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); failed:=false; BEGIN PERFORM public.revoke_child_login_invitation(j6_inv); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END; IF NOT failed OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=j6_inv AND status='accepted' AND accepted_by_profile_id=j6r AND accepted_at=j6_accepted) OR NOT EXISTS(SELECT 1 FROM public.athlete_profile_relationships WHERE athlete_id=j6a AND profile_id=j6r AND role='self' AND revoked_at IS NULL AND training_permission AND manage_permission) THEN RAISE EXCEPTION 'J6 accepted revoke destructive'; END IF; RAISE NOTICE 'J6 PASS';
  SELECT count(*) INTO j_before_count FROM public.athletes; PERFORM public.revoke_child_login_invitation(j7_inv); failed:=false; BEGIN PERFORM public.revoke_child_login_invitation(j7_inv); EXCEPTION WHEN SQLSTATE 'P0001' THEN failed:=true; END; IF NOT failed OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=j7_inv AND status='revoked' AND revoked_by_profile_id=manager_id AND revoked_at IS NOT NULL) OR (SELECT count(*) FROM public.athletes)<>j_before_count THEN RAISE EXCEPTION 'J7 repeated revoke lifecycle failed'; END IF; RAISE NOTICE 'J7 PASS';
  PERFORM public.revoke_child_login_invitation(j8_inv_a); IF NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=j8_inv_a AND status='revoked') OR NOT EXISTS(SELECT 1 FROM public.child_login_invitations WHERE id=j8_inv_b AND status='pending' AND accepted_by_profile_id IS NULL AND revoked_at IS NULL) THEN RAISE EXCEPTION 'J8 exact invitation scope failed'; END IF; RAISE NOTICE 'J8 PASS'; RAISE NOTICE 'SECTION J PASS';

  -- Section K: listing is scoped to an exact active guardian+MANAGE relationship.
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-k-view@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO kv;
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-k-revoked@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO kr;
  INSERT INTO auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES(gen_random_uuid(),'authenticated','authenticated',v_marker||'-k-self@example.test',clock_timestamp(),'{"provider":"email"}'::jsonb,'{}',clock_timestamp(),clock_timestamp()) RETURNING id INTO kself;
