  PERFORM set_config('request.jwt.claim.sub',manager_id::text,true); SELECT c.invitation_id INTO ka_rev FROM public.create_child_login_invitation(ka,'ka-rev@example.test',encode(extensions.digest(repeat('L',64),'sha256'),'hex')) c; PERFORM public.revoke_child_login_invitation(ka_rev); SELECT c.invitation_id INTO ka_pending FROM public.create_child_login_invitation(ka,'ka-pending@example.test',encode(extensions.digest(repeat('M',64),'sha256'),'hex')) c; SELECT c.invitation_id INTO kb_pending FROM public.create_child_login_invitation(kb,'kb@example.test',encode(extensions.digest(repeat('N',64),'sha256'),'hex')) c; INSERT INTO public.athlete_profile_relationships(athlete_id,profile_id,role,training_permission,manage_permission,created_by_profile_id) VALUES(ka,kself,'self',true,true,manager_id);
