  PERFORM set_config('request.jwt.claim.sub',kv::text,true); SELECT count(*) INTO k_count FROM public.list_my_child_login_invitations(ka); IF k_count<>0 THEN RAISE EXCEPTION 'K2 view disclosure'; END IF; RAISE NOTICE 'K2 PASS';
  PERFORM set_config('request.jwt.claim.sub',kr::text,true); SELECT count(*) INTO k_count FROM public.list_my_child_login_invitations(ka); IF k_count<>0 THEN RAISE EXCEPTION 'K3 revoked disclosure'; END IF; RAISE NOTICE 'K3 PASS';
